#!/usr/bin/env bash
# ===================================================================
# Stammdaten der Hochschule Bremen: Fakultaeten, Studiengaenge, Module.
#
# EIN Aufruf, aus dem Wurzelverzeichnis des Repos, bei laufender
# Datenbank der gewuenschten Betriebsart:
#
#     bash stammdaten-seeder.sh
#
# Bequemer ueber das Menue: .\eportfolio.ps1, Punkt s1. Das Menue setzt
# DB_CONTAINER auf die Datenbank der gewaehlten Betriebsart; ohne die
# Variable trifft der Lauf die von DEV.
#
# Danach steht in der Datenbank:
#
#      5 Fakultaeten    FK1 bis FK5
#     75 Studiengaenge   mit Kuerzel, verteilt auf die fuenf
#   1915 Module          aus den Studienverlaeufen der Hochschule
#     75 Sammelmodule    eines je Studiengang (Contract §3.9)
#
# HERKUNFT. Die Daten sind erhoben aus der Confluence-Seite
# "Fakultaeten-Hierarchie" (Seiten-ID 34439171) und ihren Unterseiten:
# je Fakultaet eine Seite, je Studiengang eine Unterseite mit dem
# Abschnitt "Module laut Studienverlauf". Die Seiten selbst nennen als
# Quelle die Studiengangsseiten von hs-bremen.de, Stand September 2026.
# Nichts davon ist erfunden. Die Kuerzel dagegen sind vergeben und nicht
# erhoben: die Hochschule fuehrt oeffentlich nur fuer einen Teil der
# Studiengaenge eines (etwa ISS, ISTAB). Wo eines auffindbar war, steht
# es hier; sonst ist es gebildet.
#
# 7 Studiengangsseiten fuehren keine Modulliste, jede mit eigener
# Begruendung. Erfunden wird an dieser Stelle nichts; diese Studiengaenge
# bekommen nur ihr Sammelmodul:
#     - MBA in Executive Management
#       (die Hochschule veroeffentlicht keinen Studienverlauf, die Seite verweist auf das International Graduate Center)
#     - Global Management MBA
#       (die Hochschule veroeffentlicht keinen Studienverlauf, die Seite verweist auf das International Graduate Center)
#     - International Master of Business Administration (MBA) - Doppelabschluss
#       (die Hochschule veroeffentlicht keinen Studienverlauf, die Spezialisierung liegt bei den Partnerhochschulen)
#     - International Tourism Management MBA
#       (die Hochschule veroeffentlicht keinen Studienverlauf, die Seite verweist auf das International Graduate Center)
#     - Technische Informatik B. Sc.
#       (der Studiengang laeuft aus und ist in ISS aufgegangen; die Seite verweist fuer die Module auf ISS)
#     - Electronics Engineering M. Sc.
#       (kein einheitlicher Studienverlauf, das Curriculum besteht ueberwiegend aus Wahlmodulen eines Katalogs)
#     - Engineering and Management of Space Systems M. Sc.
#       (die deutsche Seite verweist fuer alle Details auf die englischsprachige Studiengangsseite)
#
# Es ist bewusst KEINE Flyway-Migration und KEIN Java-Seeder:
#   - Es ist eine Datenlieferung. Sie aendert sich, wenn die Hochschule
#     ihre Studiengangsseiten aendert, nicht wenn sich der Code aendert.
#   - Eine Migration truege sie in jede Umgebung, auch in die
#     produktive; dort gehoert der gepflegte Bestand hin.
#   - Ein ApplicationRunner kann anlegen, aber nicht aufraeumen. Zum
#     Entfernen gibt es stammdaten-seeder-entfernen.sh.
# Der DevMasterDataSeeder fuehrt seit dieser Lieferung nur noch
# Kategorien und Semester; sein Javadoc verweist hierher.
#
# WIEDERHOLBAR. Fakultaeten werden ueber ihr Kuerzel uebernommen
# (faculty.abbreviation ist unique), Studiengaenge und Module ueber
# feste ID-Praefixe ersetzt:
#     c0c00001-...  Fakultaeten
#     c0c00002-...  Studiengaenge
#     c0c00003-...  Module
# Zeilen ausserhalb dieser Praefixe fasst der Lauf nicht an; er meldet
# sie am Ende. Wer die gesamte Hierarchie loswerden will, nimmt vorher
# stammdaten-seeder-entfernen.sh.
#
# ERZEUGT, NICHT VON HAND GESCHRIEBEN. Wer hier etwas aendert, verliert
# es beim naechsten Lauf des Generators.
#
# Andere Containernamen? Ueber Umgebungsvariablen:
#   DB_CONTAINER=... bash stammdaten-seeder.sh
# ===================================================================
set -euo pipefail

DB="${DB_CONTAINER:-eportfolio-dev-db-1}"
DB_USER="${POSTGRES_USER:-eportfolio}"
DB_NAME="${POSTGRES_DB:-eportfolio}"

sql() { docker exec -i -e PGCLIENTENCODING=UTF8 "$DB" \
	psql -v ON_ERROR_STOP=1 -q -U "$DB_USER" -d "$DB_NAME" "$@"; }

abbruch() { echo; echo "ABBRUCH: $1" >&2; exit 1; }

echo "== Vorbedingungen =="
command -v docker >/dev/null 2>&1 || abbruch "docker nicht gefunden."
if [ "$(docker inspect -f '{{.State.Running}}' "$DB" 2>/dev/null)" != "true" ]; then
	abbruch "Container $DB laeuft nicht."
fi
docker exec "$DB" pg_isready -U "$DB_USER" -d "$DB_NAME" >/dev/null 2>&1 \
	|| abbruch "Die Datenbank $DB_NAME antwortet nicht."
echo "  Container $DB laeuft, Datenbank antwortet"
echo

echo "== Stand vorher =="
sql -c "
select 'Fakultaeten' as bestand, count(*) from faculty
union all select 'Studiengaenge', count(*) from study_program
union all select 'Module',        count(*) from module;"
echo

echo "== Schreiben =="
sql <<'ENDE_SQL_STAMMDATEN'
begin;

-- -------------------------------------------------------------------
-- 1) Fakultaeten
--
-- faculty.abbreviation ist unique. Eine vorhandene Zeile wird deshalb
-- uebernommen und nur im Namen berichtigt, statt ersetzt: an ihrer ID
-- haengen Studiengaenge und Projekte, und ein Austausch riesse sie ab.
-- -------------------------------------------------------------------
insert into faculty (id, name, abbreviation)
values
	('c0c00001-0000-4000-8000-000000000001', 'Wirtschaftswissenschaften', 'FK1'),
	('c0c00001-0000-4000-8000-000000000002', 'Architektur, Bau und Umwelt', 'FK2'),
	('c0c00001-0000-4000-8000-000000000003', 'Gesellschaftswissenschaften', 'FK3'),
	('c0c00001-0000-4000-8000-000000000004', 'Elektrotechnik und Informatik', 'FK4'),
	('c0c00001-0000-4000-8000-000000000005', 'Natur und Technik', 'FK5')
on conflict (abbreviation) do update set name = excluded.name;

-- -------------------------------------------------------------------
-- 2) Studiengaenge und Module: erst raeumen, dann schreiben.
--
-- Geraeumt wird nur der eigene Praefix. Projekte, die auf eine dieser
-- Zeilen zeigen, verlieren die Angabe; ohne das scheiterte das delete
-- am Fremdschluessel (alle stehen auf "no action").
-- -------------------------------------------------------------------
update project set module_id = null
where module_id in (select m.id from module m
                    join study_program sp on sp.id = m.study_program_id
                    where sp.id::text like 'c0c00002-%');

update project set study_program_id = null
where study_program_id in (select id from study_program
                           where id::text like 'c0c00002-%');

delete from module
where study_program_id in (select id from study_program
                           where id::text like 'c0c00002-%');

delete from study_program where id::text like 'c0c00002-%';

