-- -------------------------------------------------------------------
-- 3) Sammelmodul je Studiengang (Contract §3.9, seit v84).
--
-- Im Betrieb entsteht es als Nebenwirkung von
-- POST /api/admin/study-programs. Dieses Skript geht am Dienst vorbei
-- und legt es selbst an; Namensbildung und Kuerzel folgen
-- Module.collectiveFor(StudyProgram), dessen Javadoc hierher verweist.
-- -------------------------------------------------------------------
insert into module (id, name, abbreviation, study_program_id, collective)
select gen_random_uuid(),
       left('Module aus dem Studiengang ' || sp.name, 255),
       left(sp.abbreviation || '-ALLG', 64),
       sp.id,
       true
from study_program sp
where sp.id::text like 'c0c00002-%'
  and not exists (select 1 from module m
                  where m.study_program_id = sp.id and m.collective);

commit;
ENDE_SQL_STAMMDATEN
echo "  geschrieben"
echo

echo "== Stand nachher =="
sql -c "
select 'Fakultaeten' as bestand, count(*) from faculty
union all select 'Studiengaenge aus dieser Lieferung', count(*) from study_program
       where id::text like 'c0c00002-%'
union all select 'Module aus dieser Lieferung', count(*) from module m
       where m.study_program_id in (select id from study_program
                                    where id::text like 'c0c00002-%')
union all select 'davon Sammelmodule', count(*) from module m
       where m.collective and m.study_program_id in
             (select id from study_program where id::text like 'c0c00002-%');"

# Zeilen, die nicht aus dieser Lieferung stammen. Sie koennen von Hand
# ueber die Administrationsseite entstanden sein oder aus dem frueheren
# DevMasterDataSeeder, der bis zu dieser Lieferung erfundene
# Studiengaenge und Module anlegte. Der Lauf fasst sie nicht an; ohne
# diese Meldung stuenden sie unbemerkt neben den echten.
fremd=$(sql -tAc "select count(*) from study_program
                  where id::text not like 'c0c00002-%';" | tr -d '[:space:]')
if [ "$fremd" != "0" ]; then
	echo
	echo "Hinweis: $fremd Studiengaenge stammen nicht aus dieser Lieferung:"
	sql -c "select sp.abbreviation, sp.name, f.abbreviation as fakultaet
	        from study_program sp join faculty f on f.id = sp.faculty_id
	        where sp.id::text not like 'c0c00002-%'
	        order by f.abbreviation, sp.name;"
	echo "Sie bleiben stehen. Wer sie loswerden will: erst"
	echo "stammdaten-seeder-entfernen.sh, dann dieses Skript noch einmal."
fi

echo
echo "Fertig."
